VALUES ('ARCH-002-canada', 'ARCH-002', 'Canada', 'Moderate-High', 55000, 78000, 'CAD 77k-107k/year', 'Taxable', 'Express Entry (Federal Skilled Worker); Provincial Nominee Programs; LMIA-based permits', TRUE, 'MCIP/RPP (Member/Registered Professional Planner) via Canadian Institute of Planners', 'MCIP membership; some provinces require RPP designation', 'IELTS 6.0+', 12, 'Canadian Institute of Planners (CIP) / MCIP-RPP pathway', ARRAY['Land use planning', 'environmental assessment', 'Indigenous community planning', 'transit-oriented development'], 'Strong demand for planners in growing cities (Toronto, Calgary, Vancouver). Environmental planner salary averages CAD 77k-100k+. Climate-resilience and sustainable community planning increasingly in demand post-2025 wildfire/flood events.', NULL, 'CareerBeacon Canada; erieri.com 2025')
