VALUES ('ARCH-002-australia', 'ARCH-002', 'Australia', 'Moderate', 45000, 75000, 'AUD 70k-115k/year', 'Taxable', 'Skilled Nominated (190), Skilled Work Regional (491); VETASSESS skills assessment for urban/regional planners', TRUE, 'MPIA (Member, Planning Institute of Australia); AICP Certified Planner equivalent not required but PIA membership recognized', 'None formal; PIA membership via portfolio/experience assessment', 'IELTS 6.0+', 14, 'Planning Institute of Australia (PIA) membership', ARRAY['Urban infill', 'coastal and climate planning', 'infrastructure corridors', 'Aboriginal land use', 'environmental impact assessment'], 'Urban planner salary AUD 70k-102k. Regional planning in Queensland and WA especially in demand. EIA expertise (from Philippine environmental planning background) highly transferable.', NULL, 'PayScale Australia 2026; Planning Institute of Australia')
