VALUES ('ARCH-002-saudi-arabia-gulf-consulting', 'ARCH-002', 'Saudi Arabia / Gulf (Consulting)', 'Moderate', 40000, 75000, 'SAR 150k-280k/year', 'Tax-free', 'Employment visa; authenticated degree + PRC license + Saudi Embassy attestation', FALSE, 'No specific Gulf planning license; hired as ''Urban Planning Consultant'' or ''Land Use Planner''', NULL, 'English sufficient', 8, 'PIEP Saudi Arabia and Qatar Chapters (networking)', ARRAY['Master planning for Vision 2030 cities', 'NEOM district planning', 'zoning', 'land use frameworks'], 'Saudi Arabia''s Vision 2030 projects (NEOM, ROSHN, Diriyah Gate) require large numbers of urban planners. PIEP maintains active chapters in KSA and Qatar. Role is typically ''planning consultant'' rather than licensed EnP. Packages include accommodation and transport allowances.', NULL, 'PIEP International Cluster; NEOM Careers 2025')
