INSERT INTO career_destinations (id, course_id, country, demand_rating, salary_min, salary_max, salary_local, salary_type, visa_pathway, pr_pathway, credential_required, licensing_exam, language_required, timeline_months, program_name, specializations, notes, saturation_warning, source)
VALUES ('ARCH-005-australia', 'ARCH-005', 'Australia', 'High', 40000, 75000, 'AUD 62k-100k/year', 'Taxable', 'Skilled Nominated (190), Skilled Work Regional (491), Skilled Independent (189), Employer Nomination (186); VETASSESS skills assessment (AILA-endorsed)', TRUE, 'AILA membership (professional) via VETASSESS-endorsed pathway; overseas institute IFLA member required (PALA — Philippine Association of Landscape Architects is IFLA member); VETASSESS skills assessment', 'None formal; VETASSESS assessment + AILA professional membership via mentorship or senior entry pathway', 'IELTS 6.0+', 16, 'AILA VETASSESS-endorsed pathway; AILA Registered Landscape Architect (RLA) via mentorship (Feb/Aug application rounds)', ARRAY['Urban parks and streetscapes', 'coastal/waterfront design', 'bushfire recovery landscape', 'mine site rehabilitation', 'residential estate planning', 'waterway restoration'], 'Australia has an active demand for landscape architects per AILA salary survey and job listings. AILA explicitly endorses VETASSESS assessment criteria for overseas professionals. Average salary AUD 68k-100k (PayScale/SEEK 2026). AILA RLA application rounds: Feb and Aug annually. Overseas professionals whose home institute is IFLA-affiliated (PALA qualifies) can apply for ''full professional member'' fast-track. About 25% of Australian landscape architects are self-employed — also an option. PR pathway strong.', NULL, 'AILA 2025; VETASSESS; PayScale Australia 2026; SEEK Australia 2026')
