VALUES ('HLT-010-usa', 'HLT-010', 'USA', 'High', 50000, 100000, 'USD 50k-100k/year', 'Taxable', 'EB-3 (employer sponsored) or EB-1/EB-2 with NIW (National Interest Waiver for public health researchers); H-1B for specialized roles', NULL, 'Degree evaluation (WES); CHES (Certified Health Education Specialist) for health educators', 'CHES exam (optional but preferred); state health officer licensing (if applicable)', 'English proficiency; TOEFL for graduate school if applicable', 24, 'CDC Public Health Associate Program (PHAP); USAID Global Health Fellows', ARRAY['Epidemiology', 'Global Health', 'Health Policy', 'Environmental Health'], 'BLS median salary for health educators/community health workers $73,850 (2024). CDC health scientists approaching $100k+. MPH strongly recommended for advancement. Entry-level roles with BS: $50k-65k. Research and policy roles grow with experience.', 'Highly competitive for prestigious agencies (CDC, NIH, USAID); entry via NGOs and state health departments is more accessible.', 'BLS 2024, PubHealthDegrees.org, CDC PHAP')
