VALUES ('HLT-012-canada', 'HLT-012', 'Canada', 'High', 55000, 78000, 'CAD 72k-100k/year', 'Taxable', 'Express Entry (Federal Skilled Worker, TEER 2); Provincial Nominee Programs', NULL, 'CSRT national exam + provincial RT board registration (e.g., CSRT in all provinces)', 'CSRT National Respiratory Therapist Exam; foreign-trained must have credentials evaluated', 'IELTS 6.5 (varies by province)', 18, 'CSRT International Graduate pathway', ARRAY['Critical Care', 'Pediatric RT', 'Sleep Diagnostics', 'Cardiac Catheterization Lab'], 'Foreign-trained RTs must have credentials evaluated for equivalency to Canadian RT standards. Possible bridging program. Strong demand in ICU and home care sectors post-COVID. Starting salary CAD 72k; experienced RT earns CAD 90k-100k+.', NULL, 'CSRT 2025, Remitly Canada RT Guide 2025, Immigration.ca')
