VALUES ('OTH-007-canada', 'OTH-007', 'Canada', 'Moderate', 40000, 75000, 'CAD 52k-98k/year', 'Taxable', 'Study permit (for MS/PhD) then PGWP then Express Entry', NULL, 'Degree evaluation by WES; CSMLS registration for medical laboratory roles', 'CSMLS (Canadian Society for Medical Laboratory Science) exam for lab technologist roles', 'IELTS 6.5', 36, 'NSERC (Natural Sciences and Engineering Research Council) graduate scholarships', ARRAY['Biomedical Research', 'Cancer Biology', 'Infectious Disease', 'Clinical Lab Science'], 'Canada biotech sector growing in Toronto, Vancouver, Montreal. Lab technologist entry salary CAD 52k-65k. Research scientist MS-level CAD 70k-90k. PGWP gives 3 years post-graduation work authorization. Strong path from student to PR.', NULL, 'NSERC, CSMLS 2025, ImmigrationCA')
