INSERT INTO career_destinations (id, course_id, country, demand_rating, salary_min, salary_max, salary_local, salary_type, visa_pathway, pr_pathway, credential_required, licensing_exam, language_required, timeline_months, program_name, specializations, notes, saturation_warning, source)
VALUES ('OTH-014-canada', 'OTH-014', 'Canada', 'High', 75000, 103000, 'CAD 103k-105k/year (new grad); experienced CAD 120k+', 'Taxable', 'Express Entry (Federal Skilled Worker, TEER 1); Provincial Nominee Programs', NULL, 'NAVLE (North American Veterinary Licensing Examination) + provincial regulatory body registration (e.g., CVMA)', 'NAVLE (standardized North American licensing exam for vets); educational equivalency assessment via PAVE (Program for the Assessment of Veterinary Education Equivalence)', 'IELTS 6.5', 18, 'PAVE Program (Program for the Assessment of Veterinary Education Equivalence)', ARRAY['Companion Animal', 'Large Animal (cattle', 'equine)', 'Food Safety', 'Public Health Vet'], 'New grad vets earn mean CAD $103,409/year (~USD 75k). Experienced vets CAD $120k+. PAVE is the standard assessment process for non-AVMA-accredited degree programs (most PH programs). After PAVE, must pass NAVLE. Strong Express Entry points for TEER 1 healthcare professions.', 'Urban Ontario and BC small animal practices more competitive; Prairies, Atlantic Canada, and large animal practices in demand.', 'GlobalVetSalaryReport 2026, AVBC, Univet.hu 2025')
