INSERT INTO career_destinations (id, course_id, country, demand_rating, salary_min, salary_max, salary_local, salary_type, visa_pathway, pr_pathway, credential_required, licensing_exam, language_required, timeline_months, program_name, specializations, notes, saturation_warning, source)
VALUES ('IT-001-remote-global', 'IT-001', 'Remote (Global)', 'Very High', 36000, 120000, 'USD paid to PH bank or Wise/Payoneer account', 'Taxable in Philippines (TRAIN Law; declare as professional income or register as sole proprietor)', 'No visa needed — work from Philippines for foreign employer', NULL, 'Portfolio (GitHub), cloud certifications (AWS/GCP/Azure), live deployed projects', NULL, 'English — Filipinos fully qualify', 3, 'Toptal, Arc.dev, Deel, Remote.com, Upwork, Gun.io, We Work Remotely', ARRAY['Full-stack web (React/Node', 'Django', 'Laravel)', 'ML/AI (Python', 'PyTorch)', 'DevOps/SRE (Kubernetes', 'Terraform)', 'Mobile (Flutter', 'React Native)', 'Data Engineering'], 'Entry-level remote contracts start at $18—25/hour (~$36k—$50k/yr). Mid-level full-stack or backend engineers reach $50—80/hr ($100k—$160k/yr) within 3—5 years. Toptal accepts top 3% only — requires passing a grueling screening. Arc.dev and Deel are more accessible. US startups and European scale-ups are the primary hirers. Filipino CS grads are competitive because of English fluency, strong math foundations, and lower rate expectations vs. US/EU engineers. BPO/IT-BPM employers (Accenture, IBM, Cognizant, TCS) also offer quasi-international roles in Manila with USD-pegged salaries.', 'Remote tech is competitive globally. AI tools (GitHub Copilot, Cursor) are raising the output bar. Junior developers with no portfolio or specialization struggle to break through. Differentiate early.', 'Toptal rate data 2024; Arc.dev salary report 2025; Stack Overflow Developer Survey 2024; PEZA IT-BPM sector data 2025')
