INSERT INTO career_destinations (id, course_id, country, demand_rating, salary_min, salary_max, salary_local, salary_type, visa_pathway, pr_pathway, credential_required, licensing_exam, language_required, timeline_months, program_name, specializations, notes, saturation_warning, source)
VALUES ('IT-001-usa', 'IT-001', 'USA', 'Very High', 90000, 200000, 'USD', 'US taxable income', 'H-1B (Computer-related occupations SOC 15-1252, 15-1253, 15-1244 qualify as specialty occupations; annual lottery cap 65,000 regular + 20,000 master''s; registration opens March each year); O-1A (extraordinary ability — no lottery); L-1B (intracompany transfer — requires 1 yr employed abroad by same company); TN NOT available for Filipinos (USMCA is Canada/Mexico only)', NULL, 'BS CS degree evaluated by WES or NACES member; portfolio; cloud/ML certs strongly preferred; US employer sponsorship required for H-1B', 'None for software engineering; some roles (e.g., government IT) may require security clearance', 'English — no IELTS required for employment visa', 18, 'H-1B lottery (annual, March registration); O-1A extraordinary ability; F-1 OPT/STEM OPT (requires US master''s degree — 3 years OPT for STEM); L-1B intracompany', ARRAY['AI/ML engineering', 'Cloud architecture', 'Cybersecurity (see IT-002)', 'DevOps/SRE', 'Software engineering (FAANG-level pays $180k—$500k+ total comp)'], 'BLS 2024 median: Software Developers $131,450; Database Administrators $123,100; Network Architects $130,390; Information Security Analysts $124,910. FAANG/Big Tech (Google, Meta, Apple, Microsoft, Amazon) total compensation (salary + RSU + bonus) ranges $180k—$500k+ for senior engineers. H-1B lottery is the bottleneck — only ~30% of registrants get selected. Most Filipino CS professionals reach the USA via: (1) US master''s degree + STEM OPT + H-1B; (2) Canada PR first, then TN or L-1; (3) Big Tech internship to full-time conversion. Silicon Valley vs. non-tech industry: tech company salaries are 2—3x non-tech for equivalent seniority.', 'H-1B lottery is random and uncertain. Do not plan your entire career around winning the lottery in one year.', 'BLS Occupational Outlook Handbook 2024; USCIS H-1B data 2024; levels.fyi 2025')
