INSERT INTO career_destinations (id, course_id, country, demand_rating, salary_min, salary_max, salary_local, salary_type, visa_pathway, pr_pathway, credential_required, licensing_exam, language_required, timeline_months, program_name, specializations, notes, saturation_warning, source)
VALUES ('IT-001-canada', 'IT-001', 'Canada', 'Very High', 55000, 130000, 'CAD 75,000—180,000/yr', 'Canadian taxable income', 'Global Talent Stream (GTS) — Category A (employer referred by designated partner) or Category B (occupations on Global Talent Occupations List: Software Engineers NOC 21232, Computer/IT Analysts NOC 21221, Database Analysts NOC 21223); 2-week processing target; Express Entry Federal Skilled Worker (FSW) — NOC TEER 1/2/3 IT occupations qualify; Provincial Nominee Program (PNP) — BC Tech Pilot, Ontario Tech Draw, Alberta Advantage Tech Pathway', NULL, 'WES credential evaluation; BS CS accepted as equivalent to Canadian bachelor''s; no additional licensing required for software roles', 'None for software engineering', 'English — IELTS Academic or General 6.0+ required for Express Entry (Filipino applicants typically score 7.5—8.5 with no prep)', 12, 'Global Talent Stream (GTS), Express Entry FSW, BC Tech Pilot, Ontario Ignite program', ARRAY['AI/ML', 'Cloud computing', 'Full-stack development', 'Data engineering', 'Cybersecurity'], 'Canada is the most accessible high-income English-speaking destination for Filipino CS graduates. The Global Talent Stream work permit processes in 2 weeks — the fastest of any major tech destination. Toronto, Vancouver, and Waterloo are Canada''s tech hubs. Major employers: Shopify, Wealthsimple, RBC/CIBC tech divisions, Amazon Canada, Google Waterloo, Hootsuite. Entry-level salaries in Toronto: CAD 75k—100k; Vancouver: CAD 70k—95k. PR via Express Entry typically takes 6—12 months from ITA. Canada also has significant Filipino community support networks. Cost of living in Toronto/Vancouver is high; Calgary/Ottawa offer better salary-to-cost ratios.', 'Canada tech market cooled in 2023—2024 after pandemic-era hiring surge. Competition from Indian and US-laid-off engineers increased. Portfolio and specialized skills matter more now.', 'IRCC Global Talent Stream guidelines 2025; Express Entry CRS historical data; Glassdoor Canada IT salaries 2025')
