INSERT INTO career_destinations (id, course_id, country, demand_rating, salary_min, salary_max, salary_local, salary_type, visa_pathway, pr_pathway, credential_required, licensing_exam, language_required, timeline_months, program_name, specializations, notes, saturation_warning, source)
VALUES ('IT-001-singapore', 'IT-001', 'Singapore', 'High', 38000, 100000, 'SGD 52,000—135,000/yr', 'Singapore taxable income (flat 22% at S$40k, progressive above)', 'Employment Pass (EP) — minimum salary SGD 5,000/month (2025 threshold raised); Tech.Pass — for established tech professionals with 5+ years senior experience OR S$20k+/month current salary OR has founded/led a funded tech company; S Pass (mid-level, SGD 3,150/month threshold); Overseas Networks and Expertise (ONE) Pass for top talent', NULL, 'BS CS degree accepted; Singapore has no licensing requirement for software engineering; IMDA (Infocomm Media Development Authority) TechSkills Accelerator for foreign-hire endorsement', NULL, 'English — official language; Filipinos fully qualify', 6, 'Employment Pass (EP), Tech.Pass, TechSkills Accelerator (TeSA), Smart Nation Digital Transformation programs', ARRAY['FinTech', 'Blockchain', 'AI/ML', 'Cloud (Singapore is APAC cloud hub for AWS/Azure/GCP)', 'Cybersecurity'], 'Singapore is Southeast Asia''s highest-paying tech hub. Financial technology (FinTech) is the dominant sector — DBS, UOB, OCBC, GXS Bank, Grab Financial all hire heavily. Singapore''s geographic proximity to Philippines, English language, and no income tax below S$20k makes it attractive. However: EP salary threshold was raised in 2025 and COMPASS scoring system requires careful documentation. The city has a very large Filipino community. Government-linked companies (GIC, Temasek tech arms, ST Engineering, DSTA) also hire. Cost of living is high — SGD 52k may only net SGD 38k after CPF employer contribution complexity. Filipinos ineligible for CPF but can invest in SRS.', 'Singapore has increased scrutiny of Employment Pass approvals since 2023 under Fair Consideration Framework. Strong local graduate supply from NUS/NTU competes for same roles.', 'MOM Singapore EP guidelines 2025; Glassdoor Singapore tech salaries 2024—2025; IMDA Digital Economy Report 2025')
