INSERT INTO career_destinations (id, course_id, country, demand_rating, salary_min, salary_max, salary_local, salary_type, visa_pathway, pr_pathway, credential_required, licensing_exam, language_required, timeline_months, program_name, specializations, notes, saturation_warning, source)
VALUES ('IT-002-usa', 'IT-002', 'USA', 'Very High', 85000, 175000, 'USD', 'US taxable income', 'H-1B (Information Security Analysts SOC 15-1212 qualify as specialty occupation — strong case vs. general IT roles); O-1A for recognized cybersec researchers; note: government/DoD roles require US citizenship + security clearance — Filipino nationals cannot hold Top Secret clearance', NULL, 'CISSP (gold standard — requires 5 years experience), CISM (management track), CompTIA Security+/CySA+/CASP+, OSCP (offensive), CEH (offensive), CISA (audit); cloud security: AWS Certified Security Specialty, Azure Security Engineer', 'CISSP (5 years exp), CISM (5 years exp), CompTIA Security+ (no experience required — recommended before graduation)', 'English — no IELTS', 24, 'H-1B, O-1A, NSF CyberCorps: Scholarship for Service (government track, US citizens only), NICE Cybersecurity Workforce Framework', ARRAY['Cloud security', 'Zero Trust architecture', 'SIEM/SOAR implementation', 'Penetration testing', 'Incident Response', 'OT/ICS security (critical infrastructure)', 'AI security'], 'BLS 2024 median for Information Security Analysts: $124,910. Private sector (banking, healthcare, defense contractors) pays premium. Defense contractor roles (Lockheed, Raytheon, Booz Allen Hamilton) require US citizenship. Financial sector (banks, hedge funds) pays highest for cybersec — Goldman Sachs/JPMorgan cybersec roles reach $150k—$200k+ total comp. ISC2 2024: global cybersecurity workforce gap is 3.5 million — 265,000 in USA alone. H-1B case for cybersecurity is stronger than for general IT because it is more clearly a specialty occupation requiring theoretical and practical application of computer science.', 'Entry-level SOC analyst roles are plentiful but low-paid. Move to Tier 2/3 analyst, incident response, or offensive security as quickly as possible.', 'BLS OOH 2024; ISC2 Cybersecurity Workforce Study 2024; CyberSeek.org 2025; Glassdoor USA cybersecurity salary 2025')
