INSERT INTO career_destinations (id, course_id, country, demand_rating, salary_min, salary_max, salary_local, salary_type, visa_pathway, pr_pathway, credential_required, licensing_exam, language_required, timeline_months, program_name, specializations, notes, saturation_warning, source)
VALUES ('IT-002-australia', 'IT-002', 'Australia', 'Very High', 55000, 120000, 'AUD 85,000—185,000/yr', 'Australian taxable income', 'TSS 482 — Cyber Security Analyst (262112) and ICT Security Specialist (262112) are on the Medium and Long-term Strategic Skills List (MLTSSL); ACS Skills Assessment required for PR pathway; employer sponsorship for 482', NULL, 'ACS skills assessment; CISSP, CISM, CEH, CompTIA Security+ all recognized; Australian Cyber Security Centre (ACSC) Essential Eight compliance knowledge valued for government roles', 'None for private sector; government roles may require AGSVA (Australian Government Security Vetting Agency) clearance — Filipinos with PR can apply', 'IELTS 6.0+ for migration; not needed for 482 employer-sponsored', 12, 'TSS 482 ICT, ACS Skills Assessment, Australia Cyber Security Strategy 2023—2030 workforce programs, Critical Infrastructure Security sector roles', ARRAY['Critical infrastructure protection (power grid', 'water)', 'Financial sector cybersecurity (Big 4 banks)', 'Government security operations', 'Cloud security (AWS/Azure)', 'Penetration testing'], 'Australia''s Cyber Security Strategy 2023—2030 set an ambition to be a Top 3 global cybersecurity nation by 2030, creating significant demand for cybersecurity professionals. The strategy includes workforce expansion as a stated goal. Australian Signals Directorate (ASD) is a major employer but requires citizenship. Private sector is the pathway for Filipinos. Banking sector (CBA, NAB, Westpac, ANZ) has large in-house security teams. Salary range AUD 85k—120k for analysts; AUD 130k—185k for senior/management. Brisbane and Canberra have growing cybersecurity hubs with government concentration. Cost of living is lower than Sydney/Melbourne.', 'Australian employer sponsorship (482) requires demonstrated experience — fresh graduates need 1—2 years PH experience first, or Australian study.', 'Australia Cyber Security Strategy 2023-2030; Department of Home Affairs MLTSSL 2025; ACS salary guide 2025')
