INSERT INTO career_destinations (id, course_id, country, demand_rating, salary_min, salary_max, salary_local, salary_type, visa_pathway, pr_pathway, credential_required, licensing_exam, language_required, timeline_months, program_name, specializations, notes, saturation_warning, source)
VALUES ('IT-002-united-kingdom', 'IT-002', 'United Kingdom', 'High', 48000, 115000, 'GBP 38,000—90,000/yr', 'UK taxable income (20—40% progressive)', 'Skilled Worker Visa — IT Security Specialist (SOC 2136) and Cyber Security Engineer qualify; minimum salary threshold —38,700/yr (2024 increase); sponsor license required from employer; ATAS certificate not required for cybersecurity roles', NULL, 'NCSC (National Cyber Security Centre) CCP (CESG Certified Professional) scheme for senior UK government roles; CISSP, CISM, CEH recognized in private sector; CREST certifications (CREST-registered penetration tester) valued in UK', 'CREST (for penetration testing/assurance roles); CCP for government; otherwise none', 'English — no IELTS required for Skilled Worker Visa (B1 English by country of origin — Filipinos from Philippine school system qualify under English-medium education exemption)', 12, 'Skilled Worker Visa (SOC 2136), NCSC CCP Scheme, CREST UK, UK Cyber Security Council', ARRAY['Financial sector security (London FinTech)', 'Government/GCHQ contractor (citizenship required for GCHQ itself)', 'Penetration testing (active UK CREST community)', 'Cloud security', 'Incident response'], 'UK is Western Europe''s largest cybersecurity market, anchored in London. GCHQ (government signals intelligence) requires UK citizenship but large defense contractor ecosystem around it (BAE Systems Applied Intelligence, Sophos, Darktrace — all UK-based). Financial sector (HSBC, Barclays, Lloyds) has large security teams. CREST UK is the premier UK cybersecurity certification body — having a CREST penetration testing cert is almost mandatory for consultant roles. UK salary in GBP is lower than US in absolute terms but London allowances and lower healthcare cost vs. USA compensate. British culture is good fit for Filipino professionals. NHS Digital (healthcare cybersecurity) is a niche high-demand sector.', 'Post-Brexit talent market tightened 2023—2025. Salary threshold increase to —38,700 eliminated many entry-level Skilled Worker routes. Need to qualify at mid-level (2+ years experience) minimum.', 'UK Home Office Skilled Worker Visa thresholds 2024; NCSC UK Cyber Security Sector Analysis 2024; CREST membership data 2025')
