INSERT INTO career_destinations (id, course_id, country, demand_rating, salary_min, salary_max, salary_local, salary_type, visa_pathway, pr_pathway, credential_required, licensing_exam, language_required, timeline_months, program_name, specializations, notes, saturation_warning, source)
VALUES ('IT-003-canada', 'IT-003', 'Canada', 'Very High', 40000, 110000, 'CAD 55,000—150,000/yr', 'Canadian taxable income', 'Global Talent Stream Category B — Game Developers and Multimedia Artists (NOC 21234, NOC 52120 Animation) qualify; 2-week processing target; Provincial Nominee Programs in BC and Quebec have specific tech/creative programs', NULL, 'WES credential evaluation; demo reel/portfolio replaces licensing; Unity Certified Developer, Unreal Authorized Instructor certification helpful', NULL, 'English (Vancouver, Toronto); French for Quebec/Montreal — DELF B2 or TEF required for Quebec immigration but English sufficient for studio employment in Montreal', 12, 'Global Talent Stream NOC 21234/52120, Quebec Skilled Worker Program (PEQ), BC PNP Tech Pilot', ARRAY['AAA game development (Ubisoft Montreal: Assassin''s Creed', 'Rainbow Six; EA Vancouver: FIFA/EA Sports; Rockstar Toronto; Warner Bros Games Montreal)', '3D animation (Rainmaker', 'DHX Media)', 'VFX (MPC', 'DNEG Vancouver', 'Framestore)'], 'Canada, especially Montreal (Quebec) and Vancouver (BC), is arguably the world''s second-largest game development and animation hub after Los Angeles. Montreal has more game studios per capita than any city globally. Major studios present: Ubisoft (largest studio outside Paris), EA, Warner Bros Games, Square Enix, Behavior Interactive, Eidos Montreal. Vancouver hosts BioWare, Riot Games Canada, Nintendo, EA Sports. Both cities offer strong provincial immigration pathways. French language is NOT required to work in Montreal studios — internal working language is English. Quebec immigration does require French for PR but studios sponsor work permits first. Tax incentives from Canadian federal/provincial governments make Canada extremely attractive for studios to hire globally.', 'Game industry had significant layoffs 2023—2024 (Ubisoft, EA, Epic Games). Entry-level competition is high. Junior roles require strong portfolio of shipped/submitted games. Network at GDC and local game developer meetups.', 'Entertainment Software Association Canada 2025; Ubisoft/EA hiring data; ESAC State of the Industry 2025; Montreal International Game Summit 2024')
