INSERT INTO career_destinations (id, course_id, country, demand_rating, salary_min, salary_max, salary_local, salary_type, visa_pathway, pr_pathway, credential_required, licensing_exam, language_required, timeline_months, program_name, specializations, notes, saturation_warning, source)
VALUES ('IT-003-japan', 'IT-003', 'Japan', 'High', 28000, 80000, 'JPY 4,300,000—12,000,000/yr', 'Japanese taxable income (10-45% progressive; significant local tax)', 'Engineer/Specialist in Humanities/International Services (E/S/HR) visa — most common for game developers and digital artists at Japanese studios; J-Find (Japan Find — post-graduation job hunting visa, 6-month grace period to find job after graduation from Japanese or designated partner university); Artist visa (Geinojin) — not applicable for commercial game/animation work', NULL, 'BS degree + portfolio; Japanese studios increasingly accept international applicants without Japanese language (some work in English internally); Unity/Unreal + familiarity with Japanese game culture is expected', NULL, 'Japanese JLPT N3 minimum (N2 preferred) for most studios; some international-facing studios accept English-only (Square Enix has English-track roles)', 18, 'Engineer/Specialist visa, J-Find post-grad visa, Square Enix International Recruitment Program, Bandai Namco global career', ARRAY['JRPG game development (Square Enix', 'Capcom', 'Koei Tecmo)', 'Mobile gacha game development (DeNA', 'Gungho', 'Akatsuki)', 'Anime production (Toei Animation', 'Ufotable', 'Production I.G)', 'Character design and concept art'], 'Japan is the original home of the JRPG and console game genres. Major studios: Square Enix (Final Fantasy, Dragon Quest), Capcom (Monster Hunter, Street Fighter), Bandai Namco, Konami, SEGA, Nintendo, Sony Interactive Entertainment Japan Studio, Cygames. The barrier is Japanese language for most roles — but some studios (Square Enix, Gumi, DeNA) have international recruitment programs. Entry salaries are lower than North America in USD terms, but cost of living in Tokyo (outside of rent) is manageable, and the career experience/prestige of working at a legendary Japanese studio is highly valued. The anime production industry (animation) has notoriously low entry salaries for in-betweeners (JPY 1—2M/year equivalent) — Japanese animation is an exploitative industry for junior animators. Focus on game dev over anime production for financial viability.', 'Japanese animation industry pays extremely low for junior animators — below living wage in some cases. Game dev pays better. Learn Japanese; it opens far more doors and higher positions.', 'Square Enix and Bandai Namco career pages 2025; Japan Game Market Report 2025; JLPT registration data; Japan External Trade Organization (JETRO) creative industry reports')
