INSERT INTO career_destinations (id, course_id, country, demand_rating, salary_min, salary_max, salary_local, salary_type, visa_pathway, pr_pathway, credential_required, licensing_exam, language_required, timeline_months, program_name, specializations, notes, saturation_warning, source)
VALUES ('IT-003-usa', 'IT-003', 'USA', 'High', 55000, 130000, 'USD', 'US taxable income', 'H-1B (Game Developer/Multimedia Artist is trickier to qualify as specialty occupation than CS roles — argue degree requirement and theoretical knowledge); O-1A Extraordinary Ability (published work, awards such as IGF nomination, credited shipped titles on major platforms help) — no lottery; O-1B for artists (animation/VFX)', NULL, 'Portfolio, shipped game credits, ArtStation profile, Unity/Unreal certification; IAMAG portfolio standard for animation; VES (Visual Effects Society) membership for VFX professionals', NULL, 'English', 24, 'H-1B, O-1A/O-1B, Game Developer Conference (GDC) annual recruiting hub, SIGGRAPH for VFX/animation', ARRAY['Technical artist (bridging art + programming', 'very in-demand at AAA studios)', 'Cinematic animator', 'VFX artist (Nuke compositing)', 'Concept artist for film/game', 'Narrative game designer'], 'US game industry is centered in Los Angeles (Activision Blizzard, Riot, Naughty Dog, Insomniac Games), Seattle (Nintendo of America, Bungie, Valve), San Francisco Bay Area (Electronic Arts HQ, 2K Games), Austin TX (id Software, Rooster Teeth Games), and New York (Take-Two Interactive, Digital Extremes). VFX/animation: Hollywood (ILM, Digital Domain, Sony Pictures Imageworks, Pixar in Emeryville). O-1A/O-1B is often the better visa strategy for game/animation professionals because H-1B specialty occupation arguments are weaker for creative roles. Awards (IGF, BAFTA nomination), published book/article credits, or shipped titles on major consoles build the extraordinary ability case. US game industry had major layoffs 2023—2024 (Microsoft/Activision, EA, Epic) — market is tightening at junior level.', 'US game industry layoffs 2023—2024 affected 20,000+ jobs. Market is recovering but junior roles are extremely competitive. Mid-level technical roles (technical artist, tools engineer) remain in demand.', 'International Game Developers Association (IGDA) Developer Satisfaction Survey 2024; GDC State of the Game Industry 2025; BLS OES data for Multimedia Artists/Animators 2024')
