INSERT INTO career_destinations (id, course_id, country, demand_rating, salary_min, salary_max, salary_local, salary_type, visa_pathway, pr_pathway, credential_required, licensing_exam, language_required, timeline_months, program_name, specializations, notes, saturation_warning, source)
VALUES ('IT-004-singapore', 'IT-004', 'Singapore', 'High', 32000, 85000, 'SGD 44,000—115,000/yr', 'Singapore taxable income', 'Employment Pass (EP) — SGD 5,000/month threshold 2025; below threshold: S Pass (SGD 3,150/month); COMPASS scoring system evaluates degree, salary, company diversity; TechSkills Accelerator (TeSA) endorsed roles get faster EP approval', NULL, 'BS IT degree; AWS/Azure cloud certs; ITIL 4 for service management; PMP for project management; CCNA for network roles; Imda-endorsed roles get priority', NULL, 'English', 6, 'Employment Pass, S Pass, TeSA (TechSkills Accelerator), Smart Nation Digital Economy programs', ARRAY['ERP/SAP system administration', 'Cloud infrastructure', 'IT project management', 'IT service management (ITSM/ITIL)', 'Digital transformation consulting'], 'Singapore is a strong destination for BS IT graduates with specialization in ERP systems, cloud infrastructure, or IT project management. Major employers: Accenture Singapore, IBM Singapore, Deloitte Singapore, Cognizant Singapore, Capgemini, DXC Technology, NCS (National Computer Systems — government IT arm of SingTel). Large banks (DBS, UOB, OCBC) also have significant IT infrastructure teams. Singapore IT roles pay significantly above Philippine salaries but cost of living is high. Many Filipino IT professionals in Singapore work in the IT-BPM/managed services sector serving MNC clients. COMPASS scoring: BS IT from CHED-recognized Philippine university + SGD 5k+ salary + employer with >50 employees generally passes.', 'EP salary threshold increases make entry-level BS IT roles harder to qualify. Need demonstrated specialization and at least 1—2 years experience.', 'MOM Singapore EP/S Pass statistics 2025; TeSA program data 2025; LinkedIn Singapore tech hiring trends 2025')
