INSERT INTO career_destinations (id, course_id, country, demand_rating, salary_min, salary_max, salary_local, salary_type, visa_pathway, pr_pathway, credential_required, licensing_exam, language_required, timeline_months, program_name, specializations, notes, saturation_warning, source)
VALUES ('IT-004-canada', 'IT-004', 'Canada', 'High', 45000, 110000, 'CAD 62,000—150,000/yr', 'Canadian taxable income', 'Global Talent Stream Category B — IT Business Analysts (NOC 21221), Systems Analysts (NOC 21221) on Global Talent Occupations List; Express Entry FSW for NOC TEER 1/2 IT roles; PNP tech streams in BC, Ontario, Alberta', NULL, 'WES credential assessment for Express Entry; cloud certs (AWS/Azure/GCP); PMP for IT PM; ITIL 4 for service management', NULL, 'IELTS 6.0+ for PR; English for employment', 15, 'Global Talent Stream, Express Entry FSW, Ontario Tech Draw, BC PNP Tech Pilot', ARRAY['Cloud administration', 'ERP systems', 'IT project management', 'Business analysis', 'Systems integration'], 'Canada is a strong long-term destination for BS IT graduates via the Express Entry system. IT business analysts and systems analysts (NOC 21221) are classified TEER 1 in the NOC system — high priority for Express Entry. GTS work permit (2-week processing) available for qualified candidates. Major IT employers: Infosys Canada, TCS Canada, Cognizant, Capgemini, IBM Canada, Oracle Canada, Government of Canada IT (PSPC — Public Services and Procurement Canada), provincial governments (Ontario Digital Service). IT consulting firms (Big 4 and boutiques) actively recruit from the Philippines for Canadian offices via intracompany transfers. Cost of living in smaller cities (Calgary, Ottawa, Halifax) much lower than Toronto/Vancouver with comparable IT salaries.', 'IT consulting and managed services market contracted in Canada 2023—2024. Government IT remains more stable. Specialization in cloud and cybersecurity within IT roles is increasingly required.', 'IRCC Global Talent Stream Occupations List 2025; Express Entry historical draws 2025; Job Bank Canada NOC 21221 data')
