INSERT INTO career_destinations (id, course_id, country, demand_rating, salary_min, salary_max, salary_local, salary_type, visa_pathway, pr_pathway, credential_required, licensing_exam, language_required, timeline_months, program_name, specializations, notes, saturation_warning, source)
VALUES ('IT-004-australia', 'IT-004', 'Australia', 'High', 48000, 110000, 'AUD 74,000—170,000/yr', 'Australian taxable income', 'TSS 482 — ICT Systems Administrator (262113), ICT Business Analyst (261111), Network Administrator (263111) on MLTSSL; employer sponsorship required; ACS Skills Assessment for PR pathways', NULL, 'ACS Skills Assessment (ICT Business Analyst, Systems Analyst, Network Administrator); cloud certs AWS/Azure; ITIL 4; PMP; Cisco CCNA/CCNP for network roles', NULL, 'IELTS 6.0+ for skilled migration', 12, 'TSS 482 ICT, ACS Skills Assessment, Subclass 189/190, Skilled Regional visa 491 for regional IT demand', ARRAY['Cloud infrastructure (AWS/Azure migration projects)', 'IT service management', 'Network administration', 'ICT project management', 'Government digital transformation (DTA)'], 'Australia''s Digital Transformation Agency (DTA) and state government digital projects (Victoria''s Big Build IT, NSW Digital, Queensland Health IT) drive significant demand for IT professionals. Major IT employers: Telstra, Optus, DXC Technology, Fujitsu Australia, NTT Data, IBM Australia, Accenture Australia, KPMG Technology. The ACS skills assessment is the required pathway — allow 3 months. Australian IT salaries are high in AUD terms but cost of living in Sydney/Melbourne is significant. Regional Australia (Canberra for government roles, Brisbane, Adelaide) offers better quality of life at comparable AIT salaries. The Philippines Permanent Resident community in Australia is very large and provides strong support networks.', 'Australian ACS assessment for IT roles requires careful preparation — ensure your experience and qualifications align with the specific ANZSCO occupation code being assessed.', 'Department of Home Affairs MLTSSL 2025; ACS skills assessment guide 2025; Seek.com.au IT salary data 2025')
