INSERT INTO career_destinations (id, course_id, country, demand_rating, salary_min, salary_max, salary_local, salary_type, visa_pathway, pr_pathway, credential_required, licensing_exam, language_required, timeline_months, program_name, specializations, notes, saturation_warning, source)
VALUES ('IT-005-middle-east-saudi-arabia-uae-qatar', 'IT-005', 'Middle East (Saudi Arabia, UAE, Qatar)', 'High', 24000, 60000, 'Tax-free: SAR/AED/QAR equivalent USD 24,000—60,000/yr; varies by institution', 'Tax-free in all three Gulf states', 'Standard employment visa sponsored by employer (university, government ministry, hospital, corporate); POEA-accredited recruitment agencies for academic librarian placements in Saudi Arabia (KFUPM, KAU, King Saud University), UAE (NYU Abu Dhabi, AUS, Khalifa University), Qatar (Qatar National Library, Qatar University, Education City campuses including Georgetown, Northwestern, Cornell-Weill)', NULL, 'PRC Librarian License (recognized in Gulf states); BS LIS degree (DFA-apostilled); catalog-specific skills (Koha, Voyager, Millennium ILS); ALA-APA Library Support Staff Certification (LSSC) adds credibility', 'PRC Librarian Licensure Examination (LLE) — required baseline; no additional Gulf exam required', 'English for international university libraries; Arabic helpful but not required at Western-branch campuses', 6, 'POEA-accredited academic placement agencies, Qatar Foundation Education City librarian roles, KFUPM (King Fahd University of Petroleum and Minerals) library, Abu Dhabi University library consortium', ARRAY['Academic library services (university reference', 'collection development)', 'Medical librarianship (hospital information centers)', 'Corporate information management', 'Digital library management'], 'The Middle East is the fastest and most accessible international pathway for PRC Librarians. Qatar has a particularly active international library sector: Qatar National Library (QNL) is one of the most modern libraries in the world, and Education City Qatar hosts branch campuses of six US universities (Georgetown, Northwestern, Cornell, CMU, Texas A&M, VCU) — all with full library operations run to American library standards, with international librarian staff. Saudi Arabia has a rapidly expanding university library system under Vision 2030 — KFUPM, King Abdulaziz University, King Faisal Specialist Hospital libraries all hire. UAE: NYU Abu Dhabi, American University of Sharjah, UAEU, Khalifa University all have professional library staff. Filipino librarians are widely trusted and respected in Gulf academic settings — track record of professional performance established over decades. Corporate sector (oil & gas companies — Saudi Aramco, ADNOC, QatarEnergy — all have corporate libraries/information centers). Typical package includes: salary + accommodation + annual flight home.', 'Recruitment is cyclical — tied to oil prices and university budget cycles. Build networks through Philippine Librarians Association (PLA) which has Gulf chapter connections. Be cautious of illegal recruitment fees.', 'Qatar Foundation workforce data 2024-2025; Saudi Arabia Ministry of Education university expansion reports; PLA Gulf chapter activity; POEA licensed agency lists 2025')
