INSERT INTO career_destinations (id, course_id, country, demand_rating, salary_min, salary_max, salary_local, salary_type, visa_pathway, pr_pathway, credential_required, licensing_exam, language_required, timeline_months, program_name, specializations, notes, saturation_warning, source)
VALUES ('IT-005-usa', 'IT-005', 'USA', 'Moderate', 50000, 100000, 'USD', 'US taxable income', 'H-1B — Librarian qualifies as specialty occupation IF position requires master''s degree (most professional librarian roles at academic institutions do require MLS); employer sponsorship by university, hospital, or special library; TN visa NOT available for Filipinos (USMCA only)', NULL, 'ALA-accredited MLS/MLIS degree is the standard requirement for professional librarian positions in the USA — PRC LIS + BS LIS alone is typically insufficient; credential evaluation by WES for academic record; CILIP/SLA membership for special libraries', 'Some states require state certification (California, New York) for public school librarians; Academic librarians do not require state licensure but do require ALA-accredited MLS', 'English — no IELTS requirement', 48, 'ALA-accredited MLS programs (can be completed online from Philippine-based students at US universities — distance MLS programs); H-1B after completing US MLS; American Association of Law Libraries (AALL) for law libraries; Medical Library Association (MLA) for hospital libraries', ARRAY['Health sciences librarianship (hospital', 'medical school)', 'Law library management', 'Digital asset management/metadata', 'Research data management (university library)', 'Corporate information management (Special Libraries)'], 'The USA is the highest-paying destination for librarians but requires an ALA-accredited MLS degree — the BS LIS and PRC license are not accepted as professional equivalents. The good news: many ALA-accredited programs (Florida State iSchool, University of Illinois at Urbana-Champaign, San Jose State iSchool, Drexel iSchool) offer FULLY ONLINE MLS degrees — a Filipino librarian can complete the MLS online while working, then apply for H-1B sponsorship. BLS 2024: Librarians median $66,130 (academic: higher); Special librarians (corporate, government, medical) earn significantly more — $80k—$100k in major metro areas. Law librarians at Big Law firms in NYC/LA can earn $100k+. Niche demand: AI/ML libraries (knowledge management for AI training datasets) is an emerging high-pay specialty.', 'US public and academic libraries are not high-growth sectors. Special libraries (corporate, law, medical, government) pay more and have steadier demand. The MLS investment (time + money) must be evaluated carefully against career trajectory.', 'BLS OOH 2024 Librarians; ALA State of Americas Libraries 2025; ALISE LIS Education Statistics 2024')
