INSERT INTO career_destinations (id, course_id, country, demand_rating, salary_min, salary_max, salary_local, salary_type, visa_pathway, pr_pathway, credential_required, licensing_exam, language_required, timeline_months, program_name, specializations, notes, saturation_warning, source)
VALUES ('IT-005-united-kingdom', 'IT-005', 'United Kingdom', 'Moderate', 32000, 75000, 'GBP 25,000—59,000/yr', 'UK taxable income', 'Skilled Worker Visa — Librarian (SOC 2451) qualifies; minimum salary —25,000/yr for sponsored roles (but Skilled Worker threshold is —38,700 for new applicants — check current threshold; shortage occupation supplement may apply); employer sponsorship required from accredited university, NHS Trust, or British Library', NULL, 'CILIP (Chartered Institute of Library and Information Professionals) membership and eventual Chartership (MCLIP) is the UK professional standard; BS LIS + PRC license can be pathway toward CILIP associate membership; full Chartership requires evidence of professional development over 1—2 years', 'CILIP Chartership (MCLIP) — portfolio-based, not an exam; takes 1—2 years post-employment', 'English — Filipinos from Philippine school system qualify; Skilled Worker Visa does not require IELTS for English-medium educated applicants', 15, 'CILIP Chartership pathway, British Library professional roles, NHS Medical Libraries (NHS Scotland, England, Wales), JISC (Joint Information Systems Committee) digital library programs', ARRAY['Academic library management', 'NHS health information services', 'British Library curatorial roles (highly competitive', 'requires UK master''s or equivalent)', 'Law librarianship (London City legal sector)', 'Digital preservation'], 'UK has strong institutional library culture: British Library, Bodleian Libraries Oxford, Cambridge University Library, National Library of Scotland — all prestigious employers. NHS library network is a large employer of health information professionals across England, Scotland, Wales. Law firms in London (Magic Circle, Silver Circle) employ specialist law librarians and knowledge management professionals at competitive salaries. CILIP Chartership is highly respected — worth pursuing once employed. UK Skilled Worker salary threshold increase to —38,700 in 2024 is the key challenge for librarian roles — many library roles historically paid below this threshold. Some shortage occupation supplements or university exception clauses may apply. Research data management (RDM) specialists are in particular demand at UK universities due to RCUK (Research Councils UK) open access mandates.', 'UK public library sector has been hit by austerity cuts. Academic and special libraries (NHS, law, corporate) are more stable. New —38,700 salary threshold eliminates some library roles from Skilled Worker pathway.', 'CILIP Pay & Employment Survey 2024; UK Home Office Skilled Worker Visa thresholds 2024; JISC digital library staffing reports 2025')
