INSERT INTO career_destinations (id, course_id, country, demand_rating, salary_min, salary_max, salary_local, salary_type, visa_pathway, pr_pathway, credential_required, licensing_exam, language_required, timeline_months, program_name, specializations, notes, saturation_warning, source)
VALUES ('IT-005-remote-global', 'IT-005', 'Remote (Global)', 'Low', 18000, 55000, 'USD paid internationally', 'Taxable in Philippines', 'No visa needed', NULL, 'Portfolio of metadata/cataloging projects; data management skills (SQL, Python for data cleaning); digital asset management (DAM systems: Bynder, Widen, Canto); taxonomy design; knowledge management certification (CKM — Certified Knowledge Manager)', NULL, 'English', 12, 'Upwork (metadata/taxonomy contracts), AI training data labeling and curation (Scale AI, Appen, Surge AI — use LIS skills for data organization), Digital asset management roles for media companies, Remote corporate knowledge management', ARRAY['Metadata architecture for enterprise content', 'Taxonomy and ontology design', 'AI training data curation and labeling', 'Digital asset management (DAM) for media/marketing', 'Records management (ISO 15489 compliance)'], 'Remote work for LIS-trained professionals is a growing but nascent area. The most promising remote pathway is AI training data curation — companies like Scale AI, Appen, Surge AI, and Toloka hire LIS-trained workers who understand metadata, classification, and information organization to curate and label AI training datasets. This is not traditional librarianship but directly applies LIS skills. Another pathway: corporate knowledge management — Fortune 500 companies increasingly need remote knowledge managers to organize internal documentation (Confluence, Notion, SharePoint governance). Taxonomy and information architecture for large websites or enterprise knowledge bases is a niche but well-paid specialty ($40—60/hr for senior practitioners). Traditional cataloging/reference is rarely available as remote work.', 'AI data labeling at entry level is low-paid and commoditized. The premium remote LIS roles (taxonomy design, knowledge architecture) require demonstrated portfolio and specialized skills beyond traditional librarianship. This pathway requires intentional skills bridging.', 'Scale AI, Appen, Surge AI job postings 2024-2025; SLA special libraries remote work survey 2024; Upwork taxonomy/metadata category data 2025')
