INSERT INTO career_destinations (id, course_id, country, demand_rating, salary_min, salary_max, salary_local, salary_type, visa_pathway, pr_pathway, credential_required, licensing_exam, language_required, timeline_months, program_name, specializations, notes, saturation_warning, source)
VALUES ('IT-005-australia', 'IT-005', 'Australia', 'Moderate', 38000, 75000, 'AUD 58,000—115,000/yr', 'Australian taxable income', 'TSS 482 — Library Manager (224711) on MLTSSL for some roles; most librarian roles are NOT on the MLTSSL; Skilled Independent 189 requires positive skills assessment from ALIA (Australian Library and Information Association); state-nominated 190 has some inclusion', NULL, 'ALIA assessment of BS LIS + PRC; ALIA-accredited PG diploma or master''s preferred for Australian professional registration; AALIA membership available after skills assessment', 'No formal licensure exam; ALIA skills assessment + Chartership (AALIA) is the professional standard', 'IELTS 6.0+ (or PTE equivalent) for skills migration', 18, 'ALIA skills assessment, Subclass 189/190 points-tested migration, State Library of NSW/Victoria/Queensland hiring, Australian university library sector (Go8 universities)', ARRAY['Academic library services', 'School library management (teacher-librarian — requires teaching qualification)', 'Health information services (hospital libraries)', 'Government records management', 'Digital preservation'], 'Australia''s library sector is smaller than UK or USA but has active demand in academic libraries (Go8 research universities — ANU, UNSW, Monash, Melbourne, Sydney, Queensland, Adelaide, UWA) and state public library systems. ALIA (Australian Library and Information Association) is the professional body — skills assessment through ALIA is required for the points-tested PR visa pathway. The challenge: ALIA assessment of Philippine BS LIS may result in a skills assessment at Library Technician level (AQF5/6) rather than Librarian (AQF7+), which has lower points value. Completing a postgraduate qualification (either a Philippine or Australian master''s in LIS) strengthens the assessment outcome. School librarian (teacher-librarian) in Australia requires both LIS and teaching qualifications — dual-qualified individuals are in demand in remote/regional Australia.', 'ALIA skills assessment outcome for Philippine BS LIS can be uncertain. Obtain an assessment before planning the migration pathway. Many Philippine LIS graduates are assessed at Library Technician rather than Librarian level.', 'ALIA skills assessment guidelines 2025; Department of Home Affairs MLTSSL 2025; Australian university library sector employment data 2025')
