VALUES ('SOC-002-singapore', 'SOC-002', 'Singapore', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 9, NULL, '{}', 'Singapore has a high concentration of international schools (SAS, Tanglin Trust, UWC, Stamford American, AIS). Post-COVID corporate mental health initiatives have also created demand in the private sector. Smaller quota but higher pay than Gulf.', NULL, NULL)
