VALUES ('SOC-004-norway-oslo', 'SOC-004', 'Norway (Oslo)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 96, NULL, '{}', 'Norway is one of the world''s largest per-capita donors to peace processes (Oslo Accords history). NRC is actively deployable to conflict zones — more accessible for those willing to serve in active conflict areas. PRIO is one of the world''s top peace research institutes.', NULL, NULL)
