VALUES ('SOC-005-united-kingdom', 'SOC-005', 'United Kingdom', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 36, NULL, '{}', 'UK NHS has significant shortage of mental health practitioners. PWP (Psychological Wellbeing Practitioner) is an accessible entry point requiring a step-down High Intensity Therapist or Low Intensity training course (6-12 months, often employer-funded). Assistant Psychologist roles (non-HCPC registered) do hire international applicants. Full HCPC registration as Clinical Psychologist requires a D.Clin Psych — very competitive, ~1,400 applicants for ~200 places annually.', NULL, NULL)
