VALUES ('SOC-005-singapore', 'SOC-005', 'Singapore', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 9, NULL, '{}', 'Singapore has a very active I/O psychology and talent assessment industry (Aon, Willis Towers Watson, Korn Ferry all have assessment centers in SG). A BS Psychology + 2 years I/O experience can secure roles at assessment companies or MNC HR departments. Clinical registration is more stringent.', NULL, NULL)
