VALUES ('SOC-005-united-arab-emirates', 'SOC-005', 'United Arab Emirates', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 6, NULL, '{}', 'UAE has growing demand for school psychologists and student wellbeing specialists in its expanding international school sector. Corporate wellness programmes are growing. Clinical psychology licenses in UAE health facilities require master''s equivalent — but schools and HR have more accessible entry. Tax-free salaries make this financially attractive while building toward clinical credentials.', NULL, NULL)
