VALUES ('SOC-006-united-kingdom', 'SOC-006', 'United Kingdom', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 6, NULL, '{}', 'UK is experiencing a social work crisis — Social Work England data shows 10,000+ vacancies in England alone. Filipino social workers are well-regarded by UK employers for child welfare work. Major agencies: Randstad Social Work, Charles Hunter Associates, Liquid Personnel actively recruit from Philippines. Many UK councils now conduct direct recruitment in Manila. Children''s services and adult social care are both shortage areas. Key tip: children and families social work offers faster promotion and higher pay in UK.', NULL, NULL)
