VALUES ('SOC-006-australia', 'SOC-006', 'Australia', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 12, NULL, '{}', 'Australia''s NDIS (National Disability Insurance Scheme) has created massive demand for social workers as support planners and coordinators. Child protection crisis in Queensland, NSW, and WA drives large-scale recruitment. Hospital social work in major cities (Melbourne, Sydney) offers good salaries and work-life balance. State-sponsored migration (subclass 190) available from multiple states. AASW assessment typically takes 3-4 months.', NULL, NULL)
