VALUES ('SOC-006-canada', 'SOC-006', 'Canada', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 18, NULL, '{}', 'Canada has acute social work shortage across provinces. British Columbia and Alberta have fastest deployment. Quebec requires French proficiency — stick to English provinces. Child protection is highest-demand and highest-paying specialty. Settlement social work (supporting immigrants/refugees) specifically values multilingual Filipino workers. IRCC (Immigration, Refugees and Citizenship Canada) Express Entry draw includes social workers.', NULL, NULL)
