VALUES ('SOC-006-new-zealand', 'SOC-006', 'New Zealand', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 10, NULL, '{}', 'New Zealand''s Green List Tier 2 classification for social workers means eligible applicants can apply straight to residence without first getting work experience in NZ — a rare and valuable pathway. SWRB international registration is well-organized and Filipino applicants have successfully used this route. Oranga Tamariki has large vacancy numbers. Smaller market than UK/AU/CA but very direct PR pathway.', NULL, NULL)
