VALUES ('OTH-001-usa', 'OTH-001', 'USA', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 60, NULL, '{}', 'Washington D.C. has the highest concentration of policy/IR think tanks (Brookings, CSIS, Wilson Center, CNAS). Filipino political scientists are not specifically recruited but regional Asia expertise is valued. Realistic path: master''s or PhD at a US university, then OPT employment. NGO/advocacy sector (Human Rights Watch, Amnesty US) also employs policy researchers.', NULL, NULL)
