VALUES ('OTH-001-uk', 'OTH-001', 'UK', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 30, NULL, '{}', 'London is home to major political risk firms (Control Risks, IHS Markit/S&P, Oxford Analytica). Chatham House, IISS (International Institute for Strategic Studies), ODI (Overseas Development Institute) are key think tanks. All prefer master''s degree. Graduate route via UK university is most viable.', NULL, NULL)
