VALUES ('OTH-001-belgium-brussels', 'OTH-001', 'Belgium (Brussels)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 48, NULL, '{}', 'Brussels is the EU capital and NATO headquarters — significant policy employment hub but heavily biased toward EU citizens. European Parliament internships (stagiaires) are open to non-EU nationals. EU-ASEAN relations work occasionally requires Southeast Asian expertise. Very difficult without EU citizenship or EU education.', NULL, NULL)
