VALUES ('OTH-002-united-arab-emirates', 'OTH-002', 'United Arab Emirates', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 4, NULL, '{}', 'UAE is the Middle East media and PR hub. Dubai Media City and Abu Dhabi''s twofour54 are media free zones housing hundreds of media/PR/production companies. Large Filipino community provides support network. Dubai hosts regional HQs of many global PR agencies. Al Arabiya (Saudi-owned, Dubai-based) and Al Jazeera (Doha) hire multilingual media professionals. Gulf Arabic media also has Filipino content producers for Filipino community programming.', NULL, NULL)
