VALUES ('OTH-009-philippines', 'OTH-009', 'Philippines', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, '{}', 'Philippine legal market is the primary destination. Top law firms (SyCip Salazar Hernandez Gatmaitan, Romulo Mabanta, Cruz Marcelo Tenefrancia, Angara Abello) offer the best training and eventual international exposure. Government practice (OSG, DOJ, Senate/Congress legal staff) offers public service track. MNC in-house counsel (Citibank, P&G, Unilever, Accenture) pay significantly above law firm starting rates.', NULL, NULL)
