VALUES ('OTH-009-usa', 'OTH-009', 'USA', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 36, NULL, '{}', 'The LLM-to-NY-Bar route is the most common pathway for Asian foreign lawyers entering the US legal market. Top Philippine law firm experience + LLM at a T-14 school + NY Bar = competitive for US BigLaw positions in their Asia Pacific or Philippines practice groups. Filipino-American community also needs Filipino law firms. US immigration law is a growing practice area with high demand for Filipino practitioners serving the OFW/immigrant community.', NULL, NULL)
