VALUES ('OTH-009-australia', 'OTH-009', 'Australia', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 36, NULL, '{}', 'Australia has a genuine solicitor shortage in regional areas, immigration law, family law, and community legal centres. Filipino community legal services in Melbourne, Sydney, Brisbane need Filipino-speaking lawyers. The TEQSA process and PLT can take 12-18 months after arriving. Many Philippine lawyers do their Australian admission in parallel with working in non-legal roles initially.', NULL, NULL)
