VALUES ('OTH-010-philippines-dfa-deployment-worldwide', 'OTH-010', 'Philippines (DFA deployment worldwide)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 18, NULL, '{}', 'The DFA career offers genuine international postings — Philippine FSOs serve at 80+ posts worldwide. Base salary is relatively low but overseas differential, post adjustment, hardship pay, and housing allowances significantly increase take-home. Most valuable postings: UN New York, UN Geneva, WTO Geneva, ASEAN Jakarta, major bilateral posts (USA, Japan, China, Saudi, UAE). FSOE is extremely competitive — typically 50-100 slots for thousands of applicants. Senior FSOs can become ambassadors.', NULL, NULL)
