VALUES ('OTH-010-philippines-manila-based-multilaterals', 'OTH-010', 'Philippines (Manila-based Multilaterals)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 6, NULL, '{}', 'Manila is home to ADB headquarters (one of the world''s top-paying employers in the Philippines), and offices of UNDP, UNICEF, WHO, ILO, World Food Programme, IFAD, and more. These are international organization jobs that are geographically in the Philippines but with international salary scales, career development, and global networks. ADB Young Professionals Program (YPP) is particularly prestigious and competitive.', NULL, NULL)
