VALUES ('OTH-010-switzerland-geneva-bern', 'OTH-010', 'Switzerland (Geneva/Bern)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 120, NULL, '{}', 'Geneva is the home of the UN system''s most important bodies (HRC, OHCHR, WTO, ILO, WHO, UNHCR). Extremely competitive for P-level (international professional) positions. Philippine Mission to the UN Office in Geneva also occasionally has attach— openings for FSOs. French proficiency is strongly preferred — even in English-language posts, many meetings and documents are in French.', NULL, NULL)
