VALUES ('OTH-010-belgium-brussels-indonesia-asean', 'OTH-010', 'Belgium (Brussels)/Indonesia (ASEAN)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 48, NULL, '{}', 'ASEAN Secretariat in Jakarta is one of the most accessible multilateral employers for Philippine nationals (member state citizen advantage). Posts include policy, communications, legal, and administration. Salary is competitive by Indonesian standards, paid in USD/IDR equivalent with tax exemption. ASEAN-related work also happens in Brussels via ASEAN Committee in Brussels at Philippine and ASEAN embassies.', NULL, NULL)
